create table address (id int8 generated by default as identity, cep varchar(255), district varchar(255), number varchar(255), street varchar(255), city_id int8, property_id int8, primary key (id));
create table city (id int8 generated by default as identity, name varchar(255), state_id int8, primary key (id));
create table image (id int8 generated by default as identity, id_tenant int8, url varchar(255), primary key (id));
create table lead (id int8 generated by default as identity, email varchar(255), instant varchar(255), message varchar(255), name varchar(255), phone varchar(255), property_id int8, tenant_id int8, primary key (id));
create table perfis (tenant_id int8 not null, perfis int4);
create table property (id int8 generated by default as identity, area varchar(255), area_total varchar(255), bath_rooms varchar(255), condominium varchar(255), description varchar(255), goal int4, iptu varchar(255), name varchar(255), number_rooms varchar(255), price varchar(255), status_property int4, type_property int4, vacancies varchar(255), tenant_id int8, primary key (id));
create table state (id int8 generated by default as identity, name varchar(255), primary key (id));
create table tenant (id int8 generated by default as identity, creci varchar(255), domain varchar(255), email varchar(255), end_date varchar(255), last_name varchar(255), password varchar(255), renovation varchar(255), slug varchar(255), start varchar(255), status int4, verification int4, primary key (id));
create table theme (id int8 generated by default as identity, main_color varchar(255), name varchar(255), tenant_id int8, primary key (id));
create table urls (id int8 generated by default as identity, id_tenant int8, url varchar(255), property_id int8, primary key (id));
create table user_admin_perfis (user_admin_id int8 not null, perfis int4);
create table user_admin (id int8 generated by default as identity, creci varchar(255), email varchar(255), end_date varchar(255), last_name varchar(255), password varchar(255), slug varchar(255), start varchar(255), status int4, verification int4, primary key (id));
alter table if exists tenant add constraint UK_1wuu4ilo8ya2tm94iswtp6ev1 unique (email);
alter table if exists user_admin add constraint UK_owgburtx5te2evtm2sqyu926n unique (email);
alter table if exists address add constraint FKpo044ng5x4gynb291cv24vtea foreign key (city_id) references city;
alter table if exists address add constraint FKcaqh5qfje1gr350yx6yppp1tl foreign key (property_id) references property;
alter table if exists city add constraint FK6p2u50v8fg2y0js6djc6xanit foreign key (state_id) references state;
alter table if exists lead add constraint FKmymn4p8ca9x0c8950ejolfioh foreign key (tenant_id) references tenant;
alter table if exists perfis add constraint FKht3ep9ggca63jgjg4033kq8o7 foreign key (tenant_id) references tenant;
alter table if exists property add constraint FKmgtkws7pk1ya447gyseyysnnj foreign key (tenant_id) references tenant;
alter table if exists theme add constraint FKabwqgxf34n9rr749heqwawleg foreign key (tenant_id) references tenant;
alter table if exists urls add constraint FK3id6v5b8pehmfr0ib0h8rf2g7 foreign key (property_id) references property;
alter table if exists user_admin_perfis add constraint FKf9hcelnsh3qbamr9eu7i0930v foreign key (user_admin_id) references user_admin;
